import * as React from "react";

// Application Logo (Silver Scales of Justice)
const logoBase64 = "data:image/jpeg;base64,";

interface LogoProps {
  className?: string;
  size?: "sm" | "md" | "lg" | "xl";
}

const Logo: React.FC<LogoProps> = ({ className, size = "md" }) => {
  const sizeClasses = {
    sm: "h-8 w-8",
    md: "h-12 w-12",
    lg: "h-20 w-20",
    xl: "h-28 w-28",
  };

  const finalClass = className || sizeClasses[size] || "h-12 w-12";

  return (
    <img
      src={logoBase64}
      alt="شعار مكتب المحامي"
      className={`object-contain ${finalClass}`}
      onError={(e) => {
        // Fallback to static URL
        e.currentTarget.src = "/logo.jpg";
      }}
    />
  );
};

export default Logo;
